CAT = "caguardEmergency"; SEG = "EMG"
# Syllabus sections 5 and 6: health and safety (OHSA, WHMIS) and emergency response preparation.
Q = [
("Which three rights does Ontario's Occupational Health and Safety Act give workers?",
 "Know, participate, refuse", ["Know, strike, sue", "Vote, inspect, refuse", "Rest, report, resign"],
 "Workers have the right to know about hazards, to participate in health and safety, and to refuse unsafe work. These rights apply to guards like any other workers."),
("At how many regularly employed workers does an Ontario workplace normally need a joint health and safety committee?",
 "20 or more", ["6 or more", "50 or more", "100 or more"],
 "The OHSA requires a joint health and safety committee where 20 or more workers are regularly employed. Workplaces with 6 to 19 workers need a health and safety representative instead."),
("How many sections does a WHMIS safety data sheet have?",
 "16", ["8", "9", "12"],
 "A WHMIS safety data sheet (SDS) has 16 standard sections, from identification to other information. Section 4 covers first aid and section 6 accidental release."),
("Which must appear on a WHMIS supplier label?",
 "Hazard pictograms", ["The retail price", "The buyer's name", "The date of purchase"],
 "Supplier labels show the product identifier, pictograms, signal word, hazard and precautionary statements and supplier details. Price and buyer are not hazard information."),
("Under the OHSA, who must have a workplace violence and harassment policy?",
 "The employer", ["Each worker", "The client", "The local police"],
 "Ontario employers must prepare workplace violence and harassment policies and programs. Guards should know their employer's and the site's procedures."),
("In the fire response acronym RACE, what does the A stand for?",
 "Alarm", ["Attack", "Assess", "Assist"],
 "RACE is Rescue, Alarm, Contain, Extinguish or evacuate. Sounding the alarm early gets everyone moving and brings the fire service."),
("Where should you aim a portable fire extinguisher?",
 "At the base of the fire", ["At the top of the flames", "Into the smoke", "Above the fire"],
 "PASS: pull the pin, aim at the base, squeeze, sweep side to side. The base is where the fuel is burning; spraying the flames wastes the agent."),
("A Class B fire involves which fuel?",
 "Flammable liquids", ["Ordinary combustibles", "Live electrical equipment", "Combustible metals"],
 "Class B covers flammable liquids such as gasoline and solvents. Class A is ordinary combustibles like paper and wood, Class C electrical, Class D metals."),
("A fire in live electrical equipment is which class?",
 "Class C", ["Class A", "Class B", "Class D"],
 "Class C fires involve energized electrical equipment and need a non-conductive agent. Once the power is off, it may become a Class A or B fire."),
("A fire in a deep fryer of cooking oil is which class?",
 "Class K", ["Class A", "Class B", "Class D"],
 "Class K covers cooking oils and fats, which need a wet chemical extinguisher. Water on burning oil can cause a violent flare-up."),
("Why must you never use a water extinguisher on an electrical fire?",
 "You could get an electric shock", ["The water will freeze on contact", "It makes the fire Class D", "It clogs the extinguisher"],
 "Water conducts electricity, so spraying energized equipment puts the user at risk of shock. Use a Class C rated extinguisher such as CO2 or dry chemical."),
("You take a phoned-in bomb threat. What should you do?",
 "Keep them talking; note details", ["Hang up and call them back later", "Transfer the call to voicemail", "Argue that the threat is fake"],
 "Keep the caller on the line and record exact words, voice, background noise and time; that information helps police assess the threat. Then follow the site's bomb threat plan."),
("You find an unattended, suspicious package. What should you do?",
 "Leave it; clear and report", ["Open it carefully to check", "Carry it outside the building", "Shake it gently to listen"],
 "Leave it alone, move people away, and report it following the site plan. Touching or moving a possible explosive device could set it off."),
("Why avoid using a two-way radio close to a suspected explosive device?",
 "The signal could set it off", ["The noise could alert a bomber", "Radios do not work indoors", "It drains the radio battery"],
 "Some devices can be triggered by radio frequency energy, so radios and cell phones are not used near them. Use a landline or move well away first."),
("Guard training sums up protecting people in an emergency with which three steps?",
 "Contain, activate, evacuate", ["Detect, deter, detain", "Assess, arrest, advise", "Lock, leave, log"],
 "The syllabus approach is to contain the hazard, activate the emergency response and evacuate people. Arresting anyone is not part of emergency response."),
("Fire crews arrive at your site. What is your role?",
 "Meet them and guide them in", ["Leave the site immediately", "Hold them at the gate", "Take charge of the firefighters"],
 "Control access for emergency services, meet them, and give them the details they need: location, hazards and who is still inside. The fire service takes command."),
("After a break-in, what should you do until police arrive?",
 "Keep everyone out of the scene", ["Tidy up the damaged area", "Let staff collect their things", "Count the missing stock"],
 "Secure and protect the crime scene so evidence is not disturbed until the appropriate personnel take over. Cleaning up or walking through destroys evidence."),
("What does duty of care mean for a security guard?",
 "Acting as a reasonable person would", ["Doing only what the client asks", "Protecting property over people first", "Caring for staff in your free time"],
 "Duty of care is the obligation to act as a reasonable person in your position would to avoid foreseeable harm. Failing to meet it can lead to negligence claims."),
("During a fire evacuation, how should people leave the building?",
 "By the stairs, not elevators", ["By the elevators, quickly", "By the roof access", "By whichever door is nearest"],
 "Elevators can fail or open onto a fire floor, so evacuation uses stairs and the planned exit routes. The nearest door may lead toward the fire."),
("Which patrol finding is a fire hazard you should report?",
 "A fire door wedged open", ["A lit exit sign", "A charged extinguisher", "A closed stairwell door"],
 "Fire doors must close to stop smoke and fire spreading, so a wedged door is a hazard. Lit exit signs and charged extinguishers are as they should be."),
("Why monitor how many people are inside a venue?",
 "To stay within the fire limit", ["To charge everyone the right entry fee", "To keep the music volume down", "To decide when to close the bar"],
 "Occupant load limits under the Ontario Fire Code keep a building safe to evacuate. Exceeding them puts everyone at risk in an emergency."),
("A container of an unknown chemical is leaking. What should you do first?",
 "Isolate the area and get help", ["Mop it up with paper towels", "Sniff it to identify it", "Pour water on it to dilute it"],
 "Keep people away, check the label or SDS from a safe distance, and contact the site's hazmat responders or emergency services. Cleaning or diluting an unknown chemical can make it worse."),
("You believe a task is unsafe and refuse to do it. What must you do first?",
 "Report it to your supervisor", ["Leave the site for the day", "Post about it online", "Ask a coworker to do it"],
 "Under the OHSA, a worker who refuses unsafe work must report the refusal to the employer or supervisor, who then investigates. Handing the task to someone else does not remove the danger."),
("A person on your site is carrying a gun. What should you do?",
 "Get to safety and call 911", ["Try to take the gun from them", "Order them to drop it", "Follow them closely"],
 "Your own safety comes first, and armed persons are a police matter. Move people away if you can do so safely, and call 911 with what you have seen."),
("Why must you know the site's exit routes?",
 "To guide people out safely", ["To leave before anyone else", "To lock them during a fire", "To shorten your patrols"],
 "Knowing every route lets you lead an evacuation and redirect people if one exit is blocked. It is part of following the site's emergency plan."),
("The fire alarm sounds but you see no fire. What should you do?",
 "Treat it as real", ["Silence it and wait a while", "Reset the panel yourself", "Ignore it if a drill is due"],
 "Every alarm is treated as real until the fire service confirms otherwise. Silencing or resetting it without authority can cost lives."),
("A fire is too big to fight with an extinguisher. What should you do?",
 "Get out, closing doors behind", ["Try a second extinguisher", "Open the windows to let smoke out", "Wait for it to burn down"],
 "Leave, closing doors to slow the spread, raise the alarm and call the fire service. Opening windows feeds the fire with oxygen."),
("You smell gas in a building. What should you do?",
 "Avoid switches; evacuate", ["Turn on lights to look", "Use a lighter to find it", "Phone from beside the leak"],
 "A spark from a light switch, lighter or phone can ignite gas. Get people out and call the gas utility or 911 from a safe distance."),
]
